css:
@page { size: A4; margin: 0; }
* { box-sizing: border-box; }
body { margin: 0; font-family: DejaVu Sans, sans-serif; color: #10243e; background: #fff; }
.passport-sheet { border: 2px solid #10243e; min-height: 275mm; padding: 12mm; position: relative; }
.passport-header { background: #10243e; color: #fff; display: flex; justify-content: space-between; align-items: center; padding: 12px 18px; text-align: center; font-size: 15px; }
.passport-header span, .emblem span { font-size: 10px; letter-spacing: 0; }
.emblem { border: 1px solid #d5b36a; padding: 7px 18px; color: #d5b36a; font-size: 18px; }
.identity { display: flex; gap: 18px; direction: ltr; padding: 22px 0 14px; }
.photo { width: 38mm; height: 48mm; border: 1px solid #8795a6; display: flex; align-items: center; justify-content: center; color: #8795a6; overflow: hidden; }
.photo img { width: 100%; height: 100%; object-fit: cover; }
.fields { direction: rtl; flex: 1; display: grid; grid-template-columns: 1fr 1fr; gap: 9px 16px; }
.field { border-bottom: 1px solid #c9d2dc; padding-bottom: 5px; }
.field label { display: block; color: #687789; font-size: 8px; }
.field b, .field span { display: block; font-size: 12px; }
.field span { direction: ltr; text-align: right; }
.authority { border-top: 1px solid #c9d2dc; border-bottom: 1px solid #c9d2dc; padding: 10px 0; display: flex; justify-content: space-between; font-size: 10px; }
.authority strong { font-size: 11px; }
.mrz { direction: ltr; text-align: left; font-family: DejaVu Sans Mono, monospace; font-size: 11px; letter-spacing: 1px; line-height: 1.8; background: #edf1f5; border-top: 4px solid #10243e; margin-top: 24px; padding: 12px; overflow: hidden; white-space: nowrap; }
footer { position: absolute; bottom: 10mm; left: 12mm; right: 12mm; text-align: center; color: #687789; font-size: 8px; }
